18: import { Component, inject, OnDestroy, OnInit } from '@angular/core';
19: import { FormGroup, ReactiveFormsModule } from '@angular/forms';
20: import { BedOccupancy } from 'src/api/notification';
21: import { HospitalLocation } from 'src/app/shared/models/hospital-location';
22: import { FormlyFieldConfig, FormlyFormOptions, FormlyModule } from '@ngx-formly/core';
23: import { Subscription } from 'rxjs';
24: 
25: import { BedOccupancyConstants } from './common/bed-occupancy-constants';
26: import { notifierFacilityBedOccupancyFormConfigFields } from '../shared/formly/configs/bed-occupancy/notifier-facility.config';
27: import { questionBedOccupancyHtmlConfigFields } from '../shared/formly/configs/bed-occupancy/question.config';
28: import { NotificationConstants } from '../shared/notification-constants';
29: import { BedOccupancyStorageService } from '../shared/services/bed-occupancy-storage.service';
30: import { FhirBedOccupancyService } from '../shared/services/fhir-bed-occupancy.service';
31: import { bedOccupancyDummyData } from './common/dummyData';
32: import { BedOccupancyNotificationFormDefinitionService } from './services/bed-occupancy-notification-form-definition.service';
33: import { BedOccupancyClipboardDataService } from './services/clipboard/bed-occupancy-clipboard-data.service';
