35: import { MessageDialogService, MaxHeightContentContainerComponent } from '@gematik/demis-portal-core-library';
36: import { BedOccupancyFormModel } from '../shared/models/bed-occupancy-form-model';
37: 
38: /**
39:  * @deprecated: this component can be removed with FEATURE_FLAG_PORTAL_BED_OCCUPANCY_SIDENAV
40:  */
41: @Component({
42:   selector: 'app-bed-occupancy',
43:   templateUrl: './bed-occupancy.component.html',
44:   styleUrls: ['./bed-occupancy.component.scss'],
45:   imports: [MaxHeightContentContainerComponent, ReactiveFormsModule, FormlyModule],
46: })
47: export class BedOccupancyComponent implements OnInit, OnDestroy {
48:   private readonly bedOccupancyStorageService = inject(BedOccupancyStorageService);
49:   dialog = inject(MatDialog);
50:   private readonly fhirBedOccupancyService = inject(FhirBedOccupancyService);
51:   private readonly BedOccupancyClipboardDataService = inject(BedOccupancyClipboardDataService);
52:   private readonly BedOccupancyNotificationFormDefinitionService = inject(BedOccupancyNotificationFormDefinitionService);
53:   private readonly messageDialogeService = inject(MessageDialogService);
54: 
55:   hospitalLocations: HospitalLocation[] = [];
56:   hospitalLocationsSubscription: Subscription | undefined;
57:   form = new FormGroup({});
58:   model: BedOccupancyFormModel = {
59:     //this is needed to show the email and phone field on iniital load
60:     notifierFacility: {
61:       contacts: {
62:         phoneNumbers: [
63:           {
64:             contactType: 'phone',
65:             value: '',
66:           },
67:         ],
68:         emailAddresses: [
69:           {
70:             contactType: 'email',
71:             value: '',
72:           },
73:         ],
74:       },
75:     },
76:   };
77:   options: FormlyFormOptions = {};
78:   fields: FormlyFieldConfig[] = [];
79:   IkNumber: string;
80:   bedOccupancyDummyData = bedOccupancyDummyData;
81: 
82:   sendFunction: (bo: BedOccupancy) => void;
83:   private copyPasteBoxData: Subscription;
84:   private copyHexHexButtonData: Subscription;
85: 
86:   constructor() {
87:     this.copyPasteBoxData = this.BedOccupancyClipboardDataService.clipboardData$.subscribe(data => {
88:       this.handlePasteBoxOrHexhexChange(data);
89:     });
90: 
91:     this.copyHexHexButtonData = this.BedOccupancyNotificationFormDefinitionService.hexhexButtonClick$.subscribe(() => {
92:       this.handlePasteBoxOrHexhexChange(bedOccupancyDummyData);
93:     });
94: 
95:     this.sendFunction = bo => {
96:       this.fhirBedOccupancyService.submitNotification(bo);
97:     };
98:   }
99: 
100:   handlePasteBoxOrHexhexChange(data: BedOccupancyFormModel) {
101:     if (data === null) {
102:       return;
103:     }
104:     this.model = { ...this.model, ...data };
105:     this.markFormGroupTouched(this.form);
106:   }
107: 
108:   markFormGroupTouched(formGroup: FormGroup) {
109:     Object.keys(formGroup.controls).forEach(key => {
110:       const control = formGroup.get(key);
111:       if (control instanceof FormGroup) {
112:         this.markFormGroupTouched(control);
113:       } else {
114:         control.markAsTouched();
115:       }
116:     });
117:   }
118: 
119:   submit() {
120:     const transformedData = this.fhirBedOccupancyService.transformData(this.model);
121:     //set data to storage
122:     this.bedOccupancyStorageService.setLocalStorageBedOccupancyData(this.IkNumber, {
123:       ...this.model.notifierFacility,
124:     });
125:     this.sendFunction(transformedData);
126:   }
127: 
128:   ngOnInit(): void {
129:     this.hospitalLocationsSubscription = this.bedOccupancyStorageService.fetchHospitalLocations().subscribe({
130:       next: (locations: HospitalLocation[]) => {
131:         this.hospitalLocations = locations;
132:         //looking for the IK Number
133:         this.IkNumber = locations[0]?.ik || 'not-provided';
134:         const notifierFields = notifierFacilityBedOccupancyFormConfigFields(this.IkNumber, this.hospitalLocations);
135:         this.fields = [
136:           {
137:             key: '',
138:             type: BedOccupancyConstants.DEMIS_FORM_WRAPPER_TEMPLATE_KEYWORD,
139:             fieldGroup: [
140:               {
141:                 key: 'notifierFacility',
142:                 props: {
143:                   label: BedOccupancyConstants.MELDENDE_EINRICHTUNG,
144:                   anchor: NotificationConstants.BED_OCCUPANCY_NOTIFIER_FACILITY,
145:                 },
146:                 fieldGroup: notifierFields,
147:               },
148:               {
149:                 key: 'bedOccupancyQuestion',
150:                 props: {
151:                   label: BedOccupancyConstants.BETTENBELEGUNG,
152:                   anchor: NotificationConstants.BED_OCCUPANCY_OCCUPIED_BEDS,
153:                 },
154:                 fieldGroup: questionBedOccupancyHtmlConfigFields,
155:               },
156:             ],
157:           },
158:         ];
159: 
160:         //retrieve data from storage
161:         if (this.bedOccupancyStorageService.getLocalStorageBedOccupancyData(this.IkNumber) !== null || undefined) {
162:           const loadedData = this.bedOccupancyStorageService.getLocalStorageBedOccupancyData(this.IkNumber);
163:           this.model = {
164:             bedOccupancyQuestion: {},
165:             notifierFacility: {
166:               ...loadedData,
167:               address: {
168:                 ...loadedData.address,
169:                 country: 'DE', //DEMIS-1801: overwrite old countryCode from storage
170:               },
171:             },
172:           };
173:         }
174:       },
175:       error: error => {
176:         const errorMessage = this.messageDialogeService.extractMessageFromError(error);
177:         this.messageDialogeService.showErrorDialog({
178:           redirectToHome: true,
179:           errorTitle: BedOccupancyConstants.ERROR_NO_LOCATIONS_DIALOG,
180:           errors: [
181:             {
182:               text: errorMessage,
183:             },
184:           ],
185:         });
186:       },
187:     });
188:   }
189: 
190:   ngOnDestroy(): void {
191:     this.hospitalLocationsSubscription?.unsubscribe();
192:     this.copyPasteBoxData.unsubscribe();
193:     this.copyHexHexButtonData.unsubscribe();
194:   }
195: }

