18: import { inject, Injectable } from '@angular/core';
19: import { BedOccupancyQuestion } from 'src/api/notification';
20: import { NGXLogger } from 'ngx-logger';
21: import { BehaviorSubject } from 'rxjs';
22: import { BedOccupancyQuestionClipboard } from './clipboard-enums';
23: import { MatDialog } from '@angular/material/dialog';
24: import { MessageDialogService } from '@gematik/demis-portal-core-library';
25: import { BedOccupancyFormModel } from '../../../shared/models/bed-occupancy-form-model';
26: 
27: @Injectable({
28:   providedIn: 'root',
29: })
30: export class BedOccupancyClipboardDataService {
31:   dialog: MatDialog;
32:   logger: NGXLogger;
33:   protected messageDialogeService: MessageDialogService;
34: 
35:   private readonly clipboardData = new BehaviorSubject<BedOccupancyFormModel | null>(null);
36: 
37:   constructor() {
38:     const dialog = inject(MatDialog);
39:     const logger = inject(NGXLogger);
40:     const messageDialogeService = inject(MessageDialogService);
41: 
42:     this.dialog = dialog;
43:     this.logger = logger;
44:     this.messageDialogeService = messageDialogeService;
45:   }
46: 
47:   clipboardData$ = this.clipboardData.asObservable();
48: 
49:   updateBedOccupancy(clipboardMap: Map<string, string>): void {
50:     const bedquestion = this.getBedOccupancyQuestionFromClipBoard(clipboardMap);
51:     this.clipboardData.next({
52:       bedOccupancyQuestion: bedquestion,
53:     });
54:   }
55: 
56:   getBedOccupancyQuestionFromClipBoard(paramMap: Map<string, string>): BedOccupancyQuestion {
57:     return {
58:       occupiedBeds: {
59:         adultsNumberOfBeds: this.setNumberValue(paramMap.get(BedOccupancyQuestionClipboard.ADULTS_OCCUPIED)),
60:         childrenNumberOfBeds: this.setNumberValue(paramMap.get(BedOccupancyQuestionClipboard.CHILDREN_OCCUPIED)),
61:       },
62:       operableBeds: {
63:         adultsNumberOfBeds: this.setNumberValue(paramMap.get(BedOccupancyQuestionClipboard.ADULTS_OPERABLE)),
64:         childrenNumberOfBeds: this.setNumberValue(paramMap.get(BedOccupancyQuestionClipboard.CHILDREN_OPERABLE)),
65:       },
66:     };
67:   }
68: 
69:   setNumberValue = (value: string): number => {
70:     if (value === undefined || value === null) {
71:       return undefined;
72:     }
73:     const numValue = +value;
74:     return !isNaN(numValue) ? numValue : undefined;
75:   };
76: }

