18: import { Component, OnInit, inject } from '@angular/core';
19: import { ActivatedRoute, RouterLink } from '@angular/router';
20: import { FieldType, FormlyFieldConfig, FormlyModule } from '@ngx-formly/core';
21: import { SideNavigationWrapperComponent } from '../side-navigation-wrapper/side-navigation-wrapper.component';
22: import { MatTabGroup, MatTab } from '@angular/material/tabs';
23: import { MaxHeightContentContainerComponent } from '@gematik/demis-portal-core-library';
24: import { MatToolbar, MatToolbarRow } from '@angular/material/toolbar';
25: import { MatButton } from '@angular/material/button';
26: import { MatIcon } from '@angular/material/icon';
27: /**
28:  * @deprecated: this component can be removed with FEATURE_FLAG_PORTAL_BED_OCCUPANCY_SIDENAV
29:  */
30: @Component({
31:   selector: 'app-form-wrapper',
32:   templateUrl: './form-wrapper.component.html',
33:   styleUrls: ['./form-wrapper.component.scss'],
34:   imports: [
35:     SideNavigationWrapperComponent,
36:     MatTabGroup,
37:     MatTab,
38:     MaxHeightContentContainerComponent,
39:     FormlyModule,
40:     MatToolbar,
41:     MatToolbarRow,
42:     RouterLink,
43:     MatButton,
44:     MatIcon,
45:   ],
46: })
47: export class FormWrapperComponent extends FieldType implements OnInit {
48:   private readonly route = inject(ActivatedRoute);
49: 
50:   selectedIndex = 0;
51:   currentFragment = '';
52: 
53:   constructor() {
54:     super();
55:   }
56: 
57:   ngOnInit(): void {
58:     this.route.fragment.subscribe(fragment => {
59:       this.currentFragment = fragment;
60:       this.handleFragmentChange();
61:     });
62:   }
63: 
64:   handleFragmentChange() {
65:     this.field.fieldGroup.forEach((field: FormlyFieldConfig, index) => {
66:       if (field.props.anchor === this.currentFragment) {
67:         this.selectedIndex = index;
68:       }
69:     });
70:   }
71: 
72:   nextStep() {
73:     if (this.selectedIndex !== this.field.fieldGroup.length) {
74:       this.selectedIndex = this.selectedIndex + 1;
75:     }
76:   }
77: 
78:   previousStep() {
79:     if (this.selectedIndex != 0) {
80:       this.selectedIndex = this.selectedIndex - 1;
81:     }
82:   }
83: 
84:   isValid(field: FormlyFieldConfig): boolean {
85:     if (field.key) {
86:       return field.formControl.valid;
87:     }
88: 
89:     return field.fieldGroup ? field.fieldGroup.every(f => this.isValid(f)) : true;
90:   }
91: }

